resources.description:
Полный профиль: базовые поля + card (templateId + fields) + platformsInfo.

card.fields без шаблона: { fieldName: { value: ..., platforms: {} } }
card.fields с шаблоном:  { fieldName: { isException: bool, default: ..., platforms: {} } }

